ALTER POLICY "enterprise_contract_read" ON "enterprise_contracts" TO public USING ((current_setting('borderless.platform_actor',true)='on' and exists(select 1 from platform_operator_grants g where g.user_id=(select current_setting('borderless.user_id',true)) and g.active)) or exists(select 1 from memberships m where m.organization_id="enterprise_contracts"."organization_id" and m.user_id=(select current_setting('borderless.user_id',true)) and m.role in ('Owner','Admin','Member','Viewer')) or (current_setting('borderless.entitlement_read_org',true)="enterprise_contracts"."organization_id" and exists(select 1 from engagements e where e.id=current_setting('borderless.entitlement_read_engagement',true) and e.organization_id="enterprise_contracts"."organization_id" and e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status not in ('Draft','Canceled') and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now()))));--> statement-breakpoint
ALTER POLICY "entitlement_usage_read" ON "entitlement_usage" TO public USING (exists(select 1 from memberships m where m.organization_id="entitlement_usage"."organization_id" and m.user_id=(select current_setting('borderless.user_id',true)) and m.role in ('Owner','Admin','Member','Viewer')) or (current_setting('borderless.platform_actor',true)='on' and exists(select 1 from platform_operator_grants g where g.user_id=(select current_setting('borderless.user_id',true)) and g.active)) or (current_setting('borderless.entitlement_read_org',true)="entitlement_usage"."organization_id" and exists(select 1 from engagements e where e.id=current_setting('borderless.entitlement_read_engagement',true) and e.organization_id="entitlement_usage"."organization_id" and e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status not in ('Draft','Canceled') and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now()))));